<script setup>
import {computed,onMounted,ref} from "vue";
import {NButton,NEmpty,NInput,NModal,NSelect,NTag,NForm,NFormItem,NDrawer,NDrawerContent,NAlert,useMessage,useDialog} from "naive-ui";
import PageShell from "../components/PageShell.vue";import Panel from "../components/Panel.vue";
import {mcpApi,http} from "../api.js";import {can} from "../access.js";
const message=useMessage(),dialog=useDialog();
const servers=ref([]),loading=ref(false),error=ref(""),busy=ref(false),showCreate=ref(false),editing=ref(null),detail=ref(null),selectedTool=ref(null),args=ref("{}"),result=ref(null),detailOpen=ref(false);
const blank=()=>({name:"",transport:"stdio",command:"",args:"[]",url:"",headers:"",env:""});const draft=ref(blank());
const transports=[{label:"本地进程（stdio）",value:"stdio"},{label:"HTTP",value:"http"},{label:"SSE",value:"sse"}];
const totalTools=computed(()=>servers.value.reduce((n,s)=>n+(s.tools?.length??0),0));
function status(s){return !s.enabled?'已停用':s.lastError?'连接失败':s.lastStatus==='ok'?'连接正常':'待连接';}
async function load(){loading.value=true;error.value="";try{servers.value=await mcpApi.list();if(detail.value)detail.value=servers.value.find(s=>s.id===detail.value.id)??null;}catch(e){error.value=e.message;}finally{loading.value=false;}}
function edit(item){editing.value=item?.id??null;draft.value={...blank(),...(item?{name:item.name,transport:item.transport,command:item.command??"",args:JSON.stringify(item.args??[]),url:item.url??""}:{})};showCreate.value=true;}
function json(text,type){let value;try{value=JSON.parse(text);}catch{throw Error("JSON 格式不正确");}if(type==='array'?!Array.isArray(value)||value.some(v=>typeof v!=='string'):!value||typeof value!=='object'||Array.isArray(value))throw Error(type==='array'?"参数必须是字符串数组":"请填写 JSON 对象");return value;}
async function save(){busy.value=true;try{const d=draft.value;if(!d.name.trim())throw Error("请填写服务名称");const input={name:d.name.trim(),transport:d.transport};if(d.transport==='stdio'){if(!d.command.trim())throw Error("请填写启动命令");input.command=d.command.trim();input.args=json(d.args,'array');}else{if(!d.url.trim())throw Error("请填写服务地址");input.url=d.url.trim();}if(d.headers.trim())input.headers=json(d.headers);if(d.env.trim())input.env=json(d.env);const saved=editing.value?await mcpApi.patch(editing.value,input):await mcpApi.create(input);showCreate.value=false;draft.value=blank();await load();if(saved.lastError)message.warning(`服务已保存，但连接失败：${saved.lastError}`);else message.success("服务已保存");}catch(e){message.error(e.message);}finally{busy.value=false;}}
async function refresh(item){busy.value=true;try{const updated=await mcpApi.refresh(item.id);await load();if(updated.lastError)message.error(updated.lastError);else message.success("工具列表已刷新");}catch(e){message.error(e.message);}finally{busy.value=false;}}
async function toggle(item){busy.value=true;try{await mcpApi.patch(item.id,{enabled:!item.enabled});await load();}catch(e){message.error(e.message);}finally{busy.value=false;}}
function remove(item){dialog.warning({title:"删除 MCP 服务",content:`确定删除「${item.name}」？引用其工具的技能可能无法继续使用。`,positiveText:"删除",negativeText:"取消",onPositiveClick:async()=>{try{await mcpApi.remove(item.id);await load();message.success("服务已删除");}catch(e){message.error(e.message);return false;}}});}
function inspect(item){detail.value=item;detailOpen.value=true;selectedTool.value=null;result.value=null;}
async function toolToggle(tool){try{await http.patch(`/api/mcp/tools/${tool.id}`,{enabled:!tool.enabled});await load();}catch(e){message.error(e.message);}}
function test(){let parsed;try{parsed=json(args.value);}catch(e){message.error(e.message);return;}dialog.warning({title:"确认执行工具",content:"这会实际调用外部工具，可能产生业务变更。请确认参数与目标。",positiveText:"执行",negativeText:"取消",onPositiveClick:async()=>{busy.value=true;result.value=null;try{const r=await mcpApi.call(detail.value.id,selectedTool.value.name,parsed);result.value=r;if(r.isError)message.error("工具执行失败，请查看结果");}catch(e){message.error(e.message);}finally{busy.value=false;}}});}
onMounted(load);
</script>
<template><PageShell title="MCP 集成" subtitle="管理外部工具服务、连接状态和可用工具" :loading="loading" :error="error"><template #actions><n-button v-if="can('workflow.write')" type="primary" @click="edit(null)">注册服务</n-button></template>
<details class="hint" style="margin-bottom:18px"><summary>使用说明与审批规则</summary><p>会话内的高风险工具需要人工确认。服务工具在创建会话或加载技能时装入，已打开的会话不会自动更新。</p></details>
<Panel title="已注册服务" :meta="`${servers.length} 个服务 · ${totalTools} 个工具`"><n-empty v-if="!servers.length" description="还没有 MCP 服务，注册后即可使用外部工具" class="empty-state"/>
<div v-else class="table-wrap"><table class="data-table"><thead><tr><th>服务</th><th>传输方式</th><th>连接状态</th><th>工具</th><th>操作</th></tr></thead><tbody><tr v-for="item in servers" :key="item.id"><td><b>{{item.name}}</b><span v-if="item.lastError" class="secondary">{{item.lastError}}</span></td><td>{{item.transport}}</td><td><n-tag :type="!item.enabled?'default':item.lastError?'error':item.lastStatus==='ok'?'success':'info'">{{status(item)}}</n-tag></td><td>{{item.tools?.length??0}} 个</td><td><div class="action-row"><n-button size="small" @click="inspect(item)">查看工具</n-button><n-button v-if="can('workflow.write')" size="small" :loading="busy" @click="refresh(item)">刷新</n-button><details v-if="can('workflow.write')" class="more-actions"><summary>更多</summary><div class="more-menu"><n-button @click="edit(item)">配置</n-button><n-button :loading="busy" @click="toggle(item)">{{item.enabled?'停用':'启用'}}</n-button><n-button type="error" @click="remove(item)">删除</n-button></div></details></div></td></tr></tbody></table></div></Panel>
<n-modal v-model:show="showCreate" preset="card" :title="editing?'配置 MCP 服务':'注册 MCP 服务'" style="width:600px"><n-form label-placement="top"><n-form-item label="服务名称" required><n-input v-model:value="draft.name" placeholder="例如：业务数据服务"/></n-form-item><n-form-item label="连接方式"><n-select v-model:value="draft.transport" :options="transports"/></n-form-item><template v-if="draft.transport==='stdio'"><n-form-item label="启动命令" required><n-input v-model:value="draft.command" placeholder="例如：node"/></n-form-item><n-form-item label="命令参数（JSON 字符串数组）"><n-input v-model:value="draft.args" type="textarea" placeholder='["server.mjs"]'/></n-form-item><p class="hint">每个参数作为独立字符串填写，包含空格的路径也会完整保留。</p></template><n-form-item v-else label="服务地址" required><n-input v-model:value="draft.url" placeholder="http://127.0.0.1:8080/mcp"/></n-form-item><details><summary>高级配置</summary><n-form-item label="HTTP 请求头（JSON，留空沿用）"><n-input v-model:value="draft.headers" type="password" autocomplete="off"/></n-form-item><n-form-item label="进程环境变量（JSON，留空沿用）"><n-input v-model:value="draft.env" type="password" autocomplete="off"/></n-form-item></details></n-form><template #footer><div class="action-row"><n-button @click="showCreate=false;draft=blank()">取消</n-button><n-button type="primary" :loading="busy" @click="save">保存服务</n-button></div></template></n-modal>
<n-drawer v-model:show="detailOpen" :width="640"><n-drawer-content :title="detail?.name||'服务工具'" closable><p class="hint">{{detail?.tools?.length??0}} 个工具，参数结构由服务提供。</p><article v-for="tool in detail?.tools??[]" :key="tool.id" class="tool-detail"><div class="action-row"><b>{{tool.name}}</b><n-tag>{{tool.enabled?'已启用':'已停用'}}</n-tag><n-button v-if="can('workflow.write')" size="small" @click="toolToggle(tool)">{{tool.enabled?'停用工具':'启用工具'}}</n-button><n-button v-if="can('workflow.write')" size="small" @click="selectedTool=tool;args='{}';result=null">测试</n-button></div><p>{{tool.description}}</p><details><summary>参数结构</summary><pre class="json-view">{{JSON.stringify(tool.inputSchema,null,2)}}</pre></details></article><template v-if="selectedTool"><h3>测试 {{selectedTool.name}}</h3><n-input v-model:value="args" type="textarea" :autosize="{minRows:3}"/><n-button type="primary" style="margin-top:12px" :loading="busy" @click="test">确认参数并执行</n-button><pre v-if="result" class="json-view">{{result.text}}</pre></template></n-drawer-content></n-drawer></PageShell></template><style scoped>.tool-detail{padding:18px 0;border-bottom:1px solid var(--line)}</style>
